import org.springframework.data.mongodb.core.geo.GeoJsonPoint;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.stereotype.Repository;
import java.util.List;

@Repository
public class LocationRepository {
    private final MongoTemplate mongoTemplate;

    public LocationRepository(MongoTemplate mongoTemplate) {
        this.mongoTemplate = mongoTemplate;
    }

    public List<Store> findNearbyStores(double longitude, double latitude, double maxDistanceMeters) {
        GeoJsonPoint referencePoint = new GeoJsonPoint(longitude, latitude);
        Query query = new Query(Criteria.where("location").nearSphere(referencePoint).maxDistance(maxDistanceMeters));
        return mongoTemplate.find(query, Store.class);
    }
}
